SELECT tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT CAST([], 'Array(Tuple(String, String))') AS tags, grid.timestamp AS timestamp, toFloat64(1) AS value FROM (SELECT arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({start_ms:Int64}, {end_ms:Int64} + {step_ms:Int64}, {step_ms:Int64}))) AS timestamp) AS grid LEFT JOIN (SELECT point.1 AS timestamp, count() AS sample_count FROM (SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
    SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({absent_child_start_ms:Int64}, {absent_child_end_ms:Int64} + {absent_child_step_ms:Int64}, {absent_child_step_ms:Int64}))) AS eval_ts FROM (
        SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {absent_child_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({absent_child_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({absent_child_required_end_ms:Int64})
    ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({absent_child_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({absent_child_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({absent_child_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({absent_child_offset_ms:Int64} + {absent_child_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
) GROUP BY tags ORDER BY tags) AS absent_child ARRAY JOIN absent_child.time_series AS point GROUP BY point.1) AS present ON present.timestamp = grid.timestamp WHERE ifNull(present.sample_count, 0) = 0 ORDER BY timestamp) AS missing_steps GROUP BY tags HAVING length(time_series) > 0
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
